import { useRef, useState } from 'preact/hooks';

import styles from './styles.module.scss';
import Popover from '../../../../../shared/Popover';
import { useSelector } from 'react-redux';
import { selectInviteLink } from '../../../slice/selectors';
import { FunctionalComponent } from 'preact';

interface Props {
  onClose: () => unknown
}

const AddFriend: FunctionalComponent<Props> = ({ onClose }: Props) => {
  const inviteLink = useSelector(selectInviteLink);
  const $ref = useRef<HTMLInputElement>();

  const [isCopied, setCopied] = useState(false);

  const handleCopy = () => {
    $ref.current.select();
    document.execCommand('copy');
    setCopied(true);
    setTimeout(() => setCopied(false), 3000);
  };

  return (
    <Popover onClose={onClose} className={styles.addFriendPopover}>
      <h2 className={styles.title}>
        Share your personal invite link with your friends to connect
      </h2>

      <div className={styles.copyInput}>
        <input ref={$ref} type="text" value={inviteLink} onClick={handleCopy} />

        <button className={isCopied ? styles.copied : ''} onClick={handleCopy}>
          {isCopied ? 'copied' : 'copy'}
        </button>
      </div>
    </Popover>
  );
};

export default AddFriend;
